export async function gate({ referenceDir, submissionDir }) {
  const fs = await import('node:fs');
  const path = await import('node:path');
  const { spawn } = await import('node:child_process');
  const crypto = await import('node:crypto');
  const { pathToFileURL } = await import('node:url');

  const token = crypto.randomBytes(32).toString('hex');
  const submissionUrl = pathToFileURL(path.join(submissionDir, 'answer.mjs')).href;
  const runnerPath = path.join(referenceDir, 'runner-' + crypto.randomBytes(8).toString('hex') + '.mjs');

  let pinned = '';
  try {
    pinned = fs.readFileSync(path.join(referenceDir, 'pinned-test-cases.txt'), 'utf8');
  } catch {
    pinned = [
      'test("empty array", () => { assert.deepStrictEqual(dedupeSorted([]), []); });',
      'test("single element", () => { assert.deepStrictEqual(dedupeSorted([5]), [5]); });',
      'test("no duplicates", () => { assert.deepStrictEqual(dedupeSorted([1, 2, 3]), [1, 2, 3]); });',
      'test("all duplicates", () => { assert.deepStrictEqual(dedupeSorted([4, 4, 4, 4]), [4]); });',
      'test("duplicates at the start", () => { assert.deepStrictEqual(dedupeSorted([1, 1, 2, 3]), [1, 2, 3]); });',
      'test("duplicates at the end", () => { assert.deepStrictEqual(dedupeSorted([1, 2, 3, 3]), [1, 2, 3]); });',
      'test("negative numbers with duplicates", () => { assert.deepStrictEqual(dedupeSorted([-3, -3, -1, 0, 0, 2]), [-3, -1, 0, 2]); });',
      'test("randomized property check against a reference oracle", () => {\n  for (let trial = 0; trial < 20; trial++) {\n    const len = 1 + Math.floor(Math.random() * 10);\n    const arr = Array.from({ length: len }, () => Math.floor(Math.random() * 5) - 2).sort((a, b) => a - b);\n    const expected = [...new Set(arr)];\n    assert.deepStrictEqual(dedupeSorted(arr), expected);\n  }\n});'
    ].join('\n');
  }

  const prefix = [
    'import assert from "node:assert/strict";',
    'import { readSync, writeSync } from "node:fs";',
    '',
    'function readAll(fd) {',
    '  const chunks = [];',
    '  const buf = Buffer.alloc(4096);',
    '  for (;;) {',
    '    let n;',
    '    try { n = readSync(fd, buf, 0, buf.length, null); }',
    '    catch (e) {',
    '      if (e && (e.code === "EAGAIN" || e.code === "EWOULDBLOCK" || e.code === "EOF")) break;',
    '      throw e;',
    '    }',
    '    if (!n) break;',
    '    chunks.push(Buffer.from(buf.subarray(0, n)));',
    '  }',
    '  return Buffer.concat(chunks).toString("utf8").trim();',
    '}',
    '',
    'const TOKEN = readAll(3);',
    '',
    'function report(payload) {',
    '  try { writeSync(4, Buffer.from(JSON.stringify(payload))); } catch {}',
    '}',
    '',
    'let dedupeSorted;',
    'try {',
    '  const mod = await import(' + JSON.stringify(submissionUrl) + ');',
    '  dedupeSorted = mod.dedupeSorted;',
    '} catch (e) {',
    '  report({ token: TOKEN, accept: false, reason: "import failed: " + String(e && e.message || e) });',
    '  process.exit(0);',
    '}',
    '',
    'if (typeof dedupeSorted !== "function") {',
    '  report({ token: TOKEN, accept: false, reason: "dedupeSorted is not a function" });',
    '  process.exit(0);',
    '}',
    '',
    'const tests = [];',
    'function test(name, fn) { tests.push([name, fn]); }',
    ''
  ].join('\n');

  const suffix = [
    '',
    'test("middle duplicates", () => { assert.deepStrictEqual(dedupeSorted([1, 2, 2, 2, 3]), [1, 2, 3]); });',
    'test("pair same", () => { assert.deepStrictEqual(dedupeSorted([8, 8]), [8]); });',
    'test("pair different", () => { assert.deepStrictEqual(dedupeSorted([-1, 0]), [-1, 0]); });',
    'test("all zeros", () => { assert.deepStrictEqual(dedupeSorted([0, 0, 0, 0]), [0]); });',
    'test("length 40 all sevens", () => { assert.deepStrictEqual(dedupeSorted(Array(40).fill(7)), [7]); });',
    'test("length 40 all zeros", () => { assert.deepStrictEqual(dedupeSorted(Array(40).fill(0)), [0]); });',
    'test("length 40 all negatives", () => { assert.deepStrictEqual(dedupeSorted(Array(40).fill(-3)), [-3]); });',
    'test("length 1 through 50 identical sevens", () => {',
    '  for (let n = 1; n <= 50; n++) {',
    '    assert.deepStrictEqual(dedupeSorted(Array(n).fill(7)), [7]);',
    '  }',
    '});',
    'test("length 40 two runs", () => {',
    '  const arr = Array(20).fill(1).concat(Array(20).fill(2));',
    '  assert.deepStrictEqual(dedupeSorted(arr), [1, 2]);',
    '});',
    'test("length 40 stepped pairs", () => {',
    '  const arr = Array.from({length: 40}, (_, i) => Math.floor(i / 2));',
    '  assert.deepStrictEqual(dedupeSorted(arr), [...new Set(arr)]);',
    '});',
    'test("deterministic forty sevens via push", () => {',
    '  const arr = [];',
    '  for (let i = 0; i < 40; i++) arr.push(7);',
    '  assert.deepStrictEqual(dedupeSorted(arr), [7]);',
    '});',
    'test("extended oracle large", () => {',
    '  for (let trial = 0; trial < 60; trial++) {',
    '    const len = 1 + Math.floor(Math.random() * 50);',
    '    const arr = Array.from({ length: len }, () => Math.floor(Math.random() * 21) - 10).sort((a, b) => a - b);',
    '    const expected = [...new Set(arr)];',
    '    assert.deepStrictEqual(dedupeSorted(arr), expected);',
    '  }',
    '});',
    '',
    'const expected = tests.length;',
    'let passed = 0;',
    'try {',
    '  for (const [, fn] of tests) {',
    '    fn();',
    '    passed++;',
    '  }',
    '} catch (e) {',
    '  report({ token: TOKEN, accept: false, reason: "test failed after " + passed + " passed: " + String(e && e.message || e), passed, expected });',
    '  process.exit(0);',
    '}',
    '',
    'if (passed !== expected) {',
    '  report({ token: TOKEN, accept: false, reason: "incomplete suite", passed, expected });',
    '  process.exit(0);',
    '}',
    '',
    'report({ token: TOKEN, accept: true, reason: "all " + passed + " tests passed", passed, expected });',
    'process.exit(0);',
    ''
  ].join('\n');

  const runnerSrc = prefix + '\n' + pinned + '\n' + suffix;
  fs.writeFileSync(runnerPath, runnerSrc, 'utf8');

  try {
    const outcome = await new Promise((resolve) => {
      let done = false;
      let child;
      const finish = (v) => {
        if (done) return;
        done = true;
        clearTimeout(timer);
        try { if (child) child.kill('SIGKILL'); } catch {}
        resolve(v);
      };
      const timer = setTimeout(() => finish({ accept: false, reason: 'timeout' }), 8000);

      try {
        child = spawn(process.execPath, [runnerPath], {
          stdio: ['ignore', 'ignore', 'ignore', 'pipe', 'pipe'],
          cwd: referenceDir,
          env: { PATH: process.env.PATH || '/usr/bin:/bin' }
        });
      } catch (e) {
        finish({ accept: false, reason: 'spawn error: ' + e.message });
        return;
      }

      let out = '';
      let childClosed = false;
      let fd4Ended = !child.stdio[4];

      const maybeParse = () => {
        if (!childClosed || !fd4Ended || done) return;
        try {
          const data = JSON.parse(out);
          if (data.token !== token) {
            finish({ accept: false, reason: 'attestation mismatch' });
            return;
          }
          if (data.accept === true && data.passed === data.expected && data.expected > 0) {
            finish({ accept: true, reason: String(data.reason || 'passed') });
            return;
          }
          finish({ accept: false, reason: String(data.reason || 'failed') });
        } catch {
          finish({ accept: false, reason: 'suite did not run to completion' });
        }
      };

      if (child.stdio[4]) {
        child.stdio[4].setEncoding('utf8');
        child.stdio[4].on('data', (d) => { out += d; });
        child.stdio[4].on('end', () => { fd4Ended = true; maybeParse(); });
        child.stdio[4].on('error', () => { fd4Ended = true; maybeParse(); });
      }

      child.on('error', (e) => finish({ accept: false, reason: 'spawn error: ' + e.message }));
      child.on('close', () => { childClosed = true; maybeParse(); });

      if (child.stdio[3]) {
        child.stdio[3].write(token);
        child.stdio[3].end();
      } else {
        finish({ accept: false, reason: 'no attestation channel' });
      }
    });

    return { accept: !!outcome.accept, reason: String(outcome.reason || '') };
  } finally {
    try { fs.unlinkSync(runnerPath); } catch {}
  }
}

